import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [electionResults, setElectionResults] = useState([]);
  const [loading, setLoading] = useState(true);
  const [exportLoading, setExportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("users"); // "users", "candidates", "results"

  useEffect(() => {
    // Check if admin is authenticated
    const token = localStorage.getItem("adminToken");
    if (!token) {
      navigate("/admin-login");
      return;
    }
    fetchUsers();
    fetchCandidates();
    fetchElectionResults();
  }, [navigate]);

  const fetchUsers = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get("http://localhost:5000/api/users", {
        headers: { Authorization: token },
      });
      setUsers(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching users:", error);
      if (error.response?.status === 401) {
        localStorage.removeItem("adminToken");
        navigate("/admin-login");
      }
      setLoading(false);
    }
  };

  const fetchCandidates = async () => {
    try {
      const token = localStorage.getItem("adminToken");
      const response = await axios.get("http://localhost:5000/api/candidates", {
        headers: { Authorization: token },
      });
      if (response.data.success) {
        setCandidates(response.data.candidates);
      }
    } catch (error) {
      console.error("Error fetching candidates:", error);
    }
  };

  const fetchElectionResults = async () => {
    try {
      const response = await axios.get(
        "http://localhost:5000/api/election/results"
      );
      if (response.data.success) {
        setElectionResults(response.data.results);
      }
    } catch (error) {
      console.error("Error fetching election results:", error);
    }
  };

  const exportToExcel = async () => {
    try {
      setExportLoading(true);
      const token = localStorage.getItem("adminToken");
      const response = await axios.get(
        "http://localhost:5000/api/export-excel",
        {
          headers: { Authorization: token },
          responseType: "blob",
        }
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `UserVerifications_${new Date().getTime()}.xlsx`
      );
      document.body.appendChild(link);
      link.click();
      link.remove();

      alert("✅ Excel file downloaded successfully!");
    } catch (error) {
      console.error("Error exporting Excel:", error);
      alert(
        "❌ Error exporting Excel file: " +
          (error.response?.data?.message || error.message)
      );
    } finally {
      setExportLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/admin-login");
  };

  const goToUserLogin = () => {
    navigate("/login");
  };

  const goToCandidateManagement = () => {
    navigate("/candidate-management");
  };

  const goToVoting = () => {
    navigate("/voting");
  };

  // Function to view face image
  const viewFaceImage = (faceImage) => {
    if (faceImage) {
      const imageUrl = `http://localhost:5000/uploads/${faceImage}`;
      window.open(imageUrl, "_blank");
    }
  };

  // Function to view transaction on Etherscan
  const viewTransaction = (transactionHash) => {
    if (transactionHash) {
      const etherscanUrl = `https://sepolia.etherscan.io/tx/${transactionHash}`;
      window.open(etherscanUrl, "_blank");
    }
  };

  if (loading) return <div className="loading">Loading user data...</div>;

  return (
    <div className="admin-dashboard">
      <div className="dashboard-header">
        <div>
          <h1>👨‍💼 E-Voting Admin Dashboard</h1>
          <p>
            Manage and monitor user verifications, candidates, and election
            results
          </p>
        </div>
        <div className="header-actions">
          <button onClick={goToUserLogin} className="user-login-btn">
            👤 User Login
          </button>
          <button onClick={handleLogout} className="logout-btn">
            🚪 Logout
          </button>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="dashboard-tabs">
        <button
          className={`tab-button ${activeTab === "users" ? "active" : ""}`}
          onClick={() => setActiveTab("users")}
        >
          👥 Verified Users ({users.length})
        </button>
        <button
          className={`tab-button ${activeTab === "candidates" ? "active" : ""}`}
          onClick={() => setActiveTab("candidates")}
        >
          🗳️ Candidates ({candidates.length})
        </button>
        <button
          className={`tab-button ${activeTab === "results" ? "active" : ""}`}
          onClick={() => setActiveTab("results")}
        >
          📊 Election Results
        </button>
      </div>

      <div className="dashboard-stats">
        <div className="stat-card total-users">
          <h3>Total Verified Users</h3>
          <p>{users.length}</p>
        </div>
        <div className="stat-card today-users">
          <h3>Today's Verifications</h3>
          <p>
            {
              users.filter((user) => {
                const today = new Date().toDateString();
                const userDate = new Date(user.timestamp).toDateString();
                return today === userDate;
              }).length
            }
          </p>
        </div>
        <div className="stat-card unique-voters">
          <h3>Total Candidates</h3>
          <p>{candidates.length}</p>
        </div>
        <div className="stat-card blockchain-votes">
          <h3>Blockchain Votes</h3>
          <p>
            {electionResults.reduce(
              (total, candidate) => total + parseInt(candidate.voteCount || 0),
              0
            )}
          </p>
        </div>
      </div>

      <div className="dashboard-actions">
        <button
          onClick={exportToExcel}
          className="export-btn"
          disabled={users.length === 0 || exportLoading}
        >
          {exportLoading
            ? "📊 Exporting..."
            : `📊 Export to Excel (${users.length} records)`}
        </button>
        <button
          onClick={goToCandidateManagement}
          className="manage-candidates-btn"
        >
          👥 Manage Candidates
        </button>
        <button onClick={goToVoting} className="voting-btn">
          🗳️ Go to Voting
        </button>
        <button
          onClick={() => {
            fetchUsers();
            fetchCandidates();
            fetchElectionResults();
          }}
          className="refresh-btn"
        >
          🔄 Refresh All
        </button>
      </div>

      {/* Users Tab Content */}
      {activeTab === "users" &&
        (users.length === 0 ? (
          <div className="no-data">
            <h3>📭 No user verification data found</h3>
            <p>
              Users will appear here after they complete verification through
              the user login page.
            </p>
          </div>
        ) : (
          <div className="users-table-container">
            <table className="users-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Aadhar Number</th>
                  <th>Phone Number</th>
                  <th>OTP</th>
                  <th>Face Image</th>
                  <th>Voter ID</th>
                  <th>Email</th>
                  <th>Email OTP</th>
                  <th>IP Address</th>
                  <th>Timestamp</th>
                </tr>
              </thead>
              <tbody>
                {users.map((user) => (
                  <tr key={user.ID || user.id}>
                    <td>{user.ID || user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.aadhar_number || user.aadhaar_number}</td>
                    <td>{user.phone_number}</td>
                    <td>{user.otp}</td>
                    <td>
                      {user.face_image ? (
                        <button
                          className="view-image-btn"
                          onClick={() => viewFaceImage(user.face_image)}
                          title="Click to view face image"
                        >
                          📷 View
                        </button>
                      ) : (
                        "❌"
                      )}
                    </td>
                    <td>{user.voterid || user.voter_id}</td>
                    <td>{user.email}</td>
                    <td>{user.email_otp}</td>
                    <td>{user.ip_address}</td>
                    <td>{new Date(user.timestamp).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}

      {/* Candidates Tab Content */}
      {activeTab === "candidates" && (
        <div className="candidates-section">
          <div className="section-header">
            <h2>🗳️ Election Candidates</h2>
            <p>Manage candidates for the election</p>
          </div>

          {candidates.length === 0 ? (
            <div className="no-data">
              <h3>👥 No candidates added yet</h3>
              <p>
                Click "Manage Candidates" to add candidates to the election.
              </p>
            </div>
          ) : (
            <div className="candidates-grid">
              {candidates.map((candidate) => (
                <div key={candidate.id} className="candidate-card">
                  <div className="candidate-avatar">
                    {candidate.name.charAt(0).toUpperCase()}
                  </div>
                  <div className="candidate-info">
                    <h3>{candidate.name}</h3>
                    <p className="party">{candidate.party}</p>
                    <p className="blockchain-id">
                      Blockchain ID: {candidate.blockchain_id || "N/A"}
                    </p>
                    <p className="created-date">
                      Added:{" "}
                      {new Date(candidate.created_at).toLocaleDateString()}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Election Results Tab Content */}
      {activeTab === "results" && (
        <div className="results-section">
          <div className="section-header">
            <h2>📊 Live Election Results</h2>
            <p>Real-time vote counts from blockchain</p>
          </div>

          {electionResults.length === 0 ? (
            <div className="no-data">
              <h3>📊 No election results available</h3>
              <p>Votes will appear here once users start voting.</p>
            </div>
          ) : (
            <div className="results-container">
              <div className="results-grid">
                {electionResults
                  .sort((a, b) => parseInt(b.voteCount) - parseInt(a.voteCount))
                  .map((candidate, index) => (
                    <div key={candidate.id} className="result-card">
                      <div className="result-rank">#{index + 1}</div>
                      <div className="result-candidate">
                        <h3>{candidate.name}</h3>
                        <p className="party">{candidate.party}</p>
                      </div>
                      <div className="result-votes">
                        <div className="vote-count">
                          {candidate.voteCount} votes
                        </div>
                        <div className="vote-percentage">
                          {Math.round(
                            (parseInt(candidate.voteCount) /
                              electionResults.reduce(
                                (total, c) => total + parseInt(c.voteCount),
                                0
                              )) *
                              100
                          )}
                          %
                        </div>
                      </div>
                      <div className="result-progress">
                        <div
                          className="progress-bar"
                          style={{
                            width: `${Math.round(
                              (parseInt(candidate.voteCount) /
                                electionResults.reduce(
                                  (total, c) => total + parseInt(c.voteCount),
                                  0
                                )) *
                                100
                            )}%`,
                          }}
                        ></div>
                      </div>
                    </div>
                  ))}
              </div>

              <div className="results-summary">
                <div className="summary-card">
                  <h3>📈 Election Summary</h3>
                  <div className="summary-stats">
                    <div className="stat">
                      <span className="label">Total Votes Cast:</span>
                      <span className="value">
                        {electionResults.reduce(
                          (total, candidate) =>
                            total + parseInt(candidate.voteCount || 0),
                          0
                        )}
                      </span>
                    </div>
                    <div className="stat">
                      <span className="label">Total Candidates:</span>
                      <span className="value">{electionResults.length}</span>
                    </div>
                    <div className="stat">
                      <span className="label">Leading Candidate:</span>
                      <span className="value">
                        {electionResults.length > 0
                          ? electionResults[0].name
                          : "N/A"}
                      </span>
                    </div>
                    <div className="stat">
                      <span className="label">Vote Turnout:</span>
                      <span className="value">
                        {Math.round(
                          (electionResults.reduce(
                            (total, candidate) =>
                              total + parseInt(candidate.voteCount || 0),
                            0
                          ) /
                            users.length) *
                            100
                        )}
                        %
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Blockchain Info Section */}
      <div className="blockchain-info-section">
        <h3>🔗 Blockchain Information</h3>
        <div className="blockchain-stats">
          <div className="blockchain-stat">
            <span className="label">Network:</span>
            <span className="value">Sepolia Testnet</span>
          </div>
          <div className="blockchain-stat">
            <span className="label">Contract:</span>
            <span className="value">
              {process.env.REACT_APP_CONTRACT_ADDRESS
                ? `${process.env.REACT_APP_CONTRACT_ADDRESS.substring(
                    0,
                    6
                  )}...${process.env.REACT_APP_CONTRACT_ADDRESS.substring(38)}`
                : "Not configured"}
            </span>
          </div>
          <div className="blockchain-stat">
            <span className="label">Total Transactions:</span>
            <span className="value">
              {electionResults.reduce(
                (total, candidate) =>
                  total + parseInt(candidate.voteCount || 0),
                0
              ) + candidates.length}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
